import sys

class NumberTheory:
    class Mod998:
        def __init__(self):
            self.modulus_value = 998244353
            self.factorial = [1]
            self.invFactorial = [1]

        def modulus(self):
            return self.modulus_value

        def fact(self, n):
            while len(self.factorial) <= n:
                self.factorial.append(self.mult(self.factorial[-1], len(self.factorial)))
            return self.factorial[n]

        def fInv(self, n):
            lastKnown = len(self.invFactorial) - 1
            if lastKnown < n:
                fInv = [0] * (n - lastKnown)
                fInv[0] = self.mult(self.fact(n), 1 // self.fact(n))
                for i in range(1, len(fInv)):
                    fInv[i] = self.mult(fInv[i - 1], n - i + 1)
                for i in reversed(range(len(fInv))):
                    self.invFactorial.append(fInv[i])

        def paritySign(self, k):
            return 1 if (k & 1) == 0 else self.modulus() - 1

        def ncr(self, n, r):
            if n < 0 or r < 0 or n < r:
                return 0
            return self.mult(self.fact(n), self.mult(self.fInv(r), self.fInv(n - r)))

        def smallInv(self, n):
            return self.mult(self.fInv(n), self.fact(n - 1))

        def add(self, a, b):
            v = a + b
            return v if v < self.modulus() else v - self.modulus()

        def mult(self, a, b):
            return (a * b) % self.modulus()

def main():
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    m = int(input_data[1])

    mod = NumberTheory.Mod998()
    mod.fInv(n + m)

    phaseSize = 1
    p = 1
    i = 0
    while p != 0:
        p = mod.mult(p, n - i)
        p = mod.mult(p, 1 // (n + m - i))
        phaseSize = mod.add(phaseSize, p)
        i += 1

    answer = 0
    for k in range(1, n + 1):
        term = mod.paritySign(k + 1)
        term = mod.mult(term, mod.ncr(n, k))
        term = mod.mult(term, m + k)
        term = mod.mult(term, 1 // k)
        term = mod.mult(term, phaseSize)
        answer = mod.add(answer, term)

    print(answer)

if __name__ == "__main__":
    main()

